    git("push", "-q", "origin", "HEAD:feature", cwd=clone)
    git("fetch", "-q", "origin", cwd=clone)
    git("commit", "-q", "--amend", "--allow-empty", "-m", "two again", cwd=clone)
    git("remote", "set-url", "--push", "origin", f"ssh://git@example.invalid{remote}", cwd=clone)
    pr = SimpleNamespace(
