"""Reading docs/specs: front matter, clauses, and the tests a clause names.

Shared by check-spec.py and collect-findings.py so that the mechanical pass and the
report agree on what a spec is. Standard library only, in keeping with the
repository's rule about dependencies.
"""

import re
from pathlib import Path

SPEC_DIR = Path("docs/specs")
README = SPEC_DIR / "README.md"

CLAUSE_HEADING = re.compile(r"^###\s+([A-Z]+)-(\d+)\s*:\s*(.*)$")
ANCHOR = re.compile(r'<a id="[^"]*"></a>')
VERIFIED_BY = re.compile(r"verified-by:\s*([^`\n]+)")
TEST_FN = re.compile(r"^\s*fn\s+([A-Za-z0-9_]+)\s*\(")
EM_DASH = "—"


class Clause:
    def __init__(self, spec, prefix, number, title, line):
        self.spec = spec
        self.prefix = prefix
        self.number = number
        self.title = title
        self.line = line
        self.body = []
        self.verified_by = []

    @property
    def id(self):
        return f"{self.prefix}-{self.number}"

    @property
    def text(self):
        return "\n".join(self.body)

    @property
    def canonical(self):
        """The clause as its reader has it: heading and body, with no anchor line, no trailing
        space and no blank line at either end. An anchor in a body names the clause after this
        one, so a clause added after it would otherwise reword this one."""
        return "\n".join([f"{self.id}: {self.title}", *_readable(self.body)])

    @property
    def withdrawn(self):
        return "withdrawn" in self.title.lower()

    def as_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "line": self.line,
            "verified_by": self.verified_by,
            "withdrawn": self.withdrawn,
        }


class Spec:
    def __init__(self, path):
        self.path = path
        self.rel = str(path)
        self.name = path.name
        self.front = {}
        self.front_lines = {}
        self.clauses = []
        self.lines = []
        self.frame = []
        self.malformed_front_matter = False

    @property
    def id(self):
        return self.front.get("id", "")

    @property
    def governs(self):
        return self.front.get("governs", [])

    @property
    def documented_by(self):
        """The website pages describing this spec, or a single `none (why)`. One value reads better
        written inline than as a one-item list, so a scalar and a list mean the same thing here."""
        value = self.front.get("documented-by", [])
        return [value] if isinstance(value, str) else value

    @property
    def guards(self):
        return [
            entry["symbol"] if isinstance(entry, dict) else entry
            for entry in self.front.get("guards", [])
        ]

    @property
    def pinned_guards(self):
        """The guards entries that pin where they may be used. The one definition of what
        counts as pinned, since a caller that asks how many entries pin their sites and a
        caller that asks which sites a symbol pins have to agree."""
        return [
            entry
            for entry in self.front.get("guards", [])
            if isinstance(entry, dict) and "sites" in entry
        ]

    @property
    def allowlists(self):
        """Symbol to the `path: count` items it pins. A symbol absent from this mapping pins
        nothing, which is not the same as one that pins no sites at all. What was written under
        `sites:` is passed through as it was read, so a value that is not a list of those items
        is reported rather than quietly treated as pinning nothing."""
        return {entry["symbol"]: entry["sites"] for entry in self.pinned_guards}

    @property
    def every_spelling(self):
        """The pinned symbols whose entry says `every-spelling: yes`: for those, a use written in a
        form the count does not read is an error rather than a count that quietly misses it. Opt-in
        because it asks that the bare method name be written nowhere else in the tree, which is
        true of `declassify` and false of `present`."""
        return {
            entry["symbol"]
            for entry in self.pinned_guards
            if entry.get("every-spelling") == "yes"
        }

    @property
    def commentary(self):
        """Everything outside a clause. Binds nobody, but still gets read."""
        clause_lines = {c.line for c in self.clauses}
        if not clause_lines:
            return "\n".join(self.lines)
        first = min(clause_lines)
        return "\n".join(self.lines[: first - 1])

    @property
    def frame_text(self):
        """What a reviewer reads in the spec besides the clause in front of them: the text before
        the first clause and the sections after the last, where a spec records the exceptions it
        admits. The front matter is left out, since `governs` is the one key a verdict depends on
        and a caller asks for it by name."""
        return "\n".join(_readable(self.frame))


def _readable(lines):
    """`lines` as a reader sees them: no anchor line, no trailing space, no blank line at the ends."""
    kept = [line.rstrip() for line in lines if not ANCHOR.fullmatch(line.strip())]
    while kept and not kept[-1]:
        kept.pop()
    while kept and not kept[0]:
